/* Echo Lingo service worker. Generated by engine/build_pwa.py — edit the template, not sw.js. */
const VERSION = '__VERSION__';
const BUILD = '__FP__'; // content fingerprint: any changed file → new sw.js → phones see an update
const SHELL_CACHE = `echo-lingo-shell-${VERSION}-${BUILD}`;
const AUDIO_CACHE = 'echo-lingo-audio'; // audio files are content-named, so they survive updates
const FILES = __FILES__;

// Install: download the whole new version in the background, then wait for the user to press Update.
self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(SHELL_CACHE).then((c) => c.addAll(FILES.map((f) => new Request(f, { cache: 'reload' })))));
});

// Activate: drop old app versions (keep audio).
self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith('echo-lingo-shell-') && key !== SHELL_CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

// The page's Update button sends this.
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
  if (event.data && event.data.type === 'VERSION') event.source.postMessage({ type: 'VERSION', version: VERSION });
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;

  // Audio: cache-first, saved as it's played (or via "Save audio for offline").
  if (url.pathname.includes('/audio/') && url.pathname.endsWith('.mp3')) {
    event.respondWith((async () => {
      const cache = await caches.open(AUDIO_CACHE);
      const hit = await cache.match(req);
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok) cache.put(req, res.clone());
      return res;
    })());
    return;
  }

  // App files and lessons: serve this installed version (works offline). New versions arrive via Update.
  // Anything not in the app (other pages on the site) comes from the network; offline, pages fall back to a saved copy.
  event.respondWith((async () => {
    const cache = await caches.open(SHELL_CACHE);
    const hit = await cache.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch (err) {
      if (req.mode === 'navigate') {
        const page = url.pathname.endsWith('download.html') ? 'download.html' : 'index.html';
        const saved = await cache.match(page);
        if (saved) return saved;
      }
      throw err;
    }
  })());
});
